import io.micrometer.core.instrument.Meter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Tag;
import io.micrometer.core.instrument.config.MeterFilter;

public final class CheckoutMetrics {
    private final MeterRegistry registry;

    public CheckoutMetrics(MeterRegistry registry, TierSource tiers) {
        this.registry = registry;
        registry.config().meterFilter(new MeterFilter() {
            @Override
            public Meter.Id map(Meter.Id id) {
                if (!id.getName().equals("checkout.requests")) return id;
                return id.withTag(Tag.of("tier", tiers.current()));
            }
        });
    }

    public void completed() {
        registry.counter("checkout.requests").increment();
    }
}

