import io.micrometer.core.instrument.simple.SimpleMeterRegistry;

public final class Scenario {
    public static void main(String[] args) {
        SimpleMeterRegistry registry = new SimpleMeterRegistry();
        try {
            CheckoutMetrics metrics = new CheckoutMetrics(registry, new TierSource());
            TierSource.REQUEST_TIER.set("basic");
            metrics.completed();
            TierSource.REQUEST_TIER.set("premium");
            metrics.completed();
            // Inspect the registered cohort counts here in a focused test.
        } finally {
            TierSource.REQUEST_TIER.remove();
            registry.close();
        }
    }
}

